#include <iostream>
#include <vector>
int main(){ std::vector<int> scores{70,82,91}; int total{};
  for(const int score : scores) total += score;
  std::cout << static_cast<double>(total)/scores.size() << '\n';
}

#include <iostream>
class Progress { int percent_; public:
 explicit Progress(int p): percent_{p} { if(p<0||p>100) throw std::invalid_argument{"percent"}; }
 int percent() const { return percent_; } };
int main(){ std::cout << Progress{75}.percent() << '\n'; }

